 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # A separator is a full uniform row/column of the same color.
    rows = [r for r in range(h) if len(set(grid[r])) == 1]
    cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    colors = {grid[r][0] for r in rows} & {grid[0][c] for c in cols}
    if not colors:
        return [row[:] for row in grid]
    color = next(iter(colors))
    sep_rows = [r for r in rows if grid[r][0] == color]
    sep_cols = [c for c in cols if grid[0][c] == color]

    def ranges(length, cuts):
        out, start = [], 0
        for cut in cuts:
            if start < cut:
                out.append((start, cut))
            start = cut + 1
        if start < length:
            out.append((start, length))
        return out

    row_parts, col_parts = ranges(h, sep_rows), ranges(w, sep_cols)
    if not row_parts or not col_parts:
        return [row[:] for row in grid]
    # The most frequent non-separator value is the blank/background color.
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != color:
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    # Find the panel containing the original motif (the panel with most marks).
    panels = [(r0, r1, c0, c1) for r0, r1 in row_parts for c0, c1 in col_parts]
    source = max(panels, key=lambda p: sum(
        grid[r][c] != background
        for r in range(p[0], p[1]) for c in range(p[2], p[3])
    ))
    sr0, sr1, sc0, sc1 = source
    sh, sw = sr1 - sr0, sc1 - sc0
    out = [row[:] for row in grid]
    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = grid[sr0 + (r-r0) % sh][sc0 + (c-c0) % sw]
    return out
